## Scales data between ranges. With just one arg the range is between 0 and 1.def escalar_a_rango(valores, minimo=0, maximo=1):			valores_nuevo	= []	viejo_min	= min(valores)	viejo_max	= max(valores)	rango_viejo	= (viejo_max*1.0) - viejo_min	rango_nuevo	= maximo - minimo	relacion	= rango_nuevo/rango_viejo		for x in valores:		escalado = ((x-viejo_min) * relacion + minimo)		valores_nuevo.append(escalado)	return valores_nuevo